//! Generated by Codex. Engine-owned epoch clock; never one timer per request.

use mudu::common::result::RS;
use mudu_sys::task::sync::{sleep_blocking, spawn_thread_named};
use std::sync::Arc;
use std::time::Duration;
use wasmtime::Engine;

pub(crate) struct EpochClock;
impl EpochClock {
    pub(crate) fn start(engine: Engine) -> RS<Arc<Self>> {
        let clock = Arc::new(Self);
        let weak = Arc::downgrade(&clock);
        spawn_thread_named("wasm-epoch", move || {
            while weak.strong_count() != 0 {
                sleep_blocking(Duration::from_millis(10));
                engine.increment_epoch();
            }
        })?;
        Ok(clock)
    }
}
